def seed_if_empty():
    existing_regions = {c.name for c in Category.query.all()}
    for name in DEFAULT_REGIONS:
        if name not in existing_regions:
            db.session.add(Category(name=name))

    if Location.query.first() is None:
        for data in DEFAULT_LOCATIONS:
            db.session.add(Location(**data))

    for category in Category.query.all():
        if category.name not in DEFAULT_REGIONS:
            db.session.delete(category)
    db.session.commit()
